package net.civeira.phylax.features.access.consentpurpose.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.access.consentpurpose.domain.ConsentPurpose;
import net.civeira.phylax.features.access.consentpurpose.domain.gateway.ConsentPurposeCursor;
import net.civeira.phylax.features.access.consentpurpose.domain.gateway.ConsentPurposeFilter;

class ConsentPurposeSlider extends Slider<ConsentPurpose> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ConsentPurposeCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ConsentPurposeFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ConsentPurposeFilter, ConsentPurposeCursor, Iterator<ConsentPurpose>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ConsentPurposeSlider(final Iterator<ConsentPurpose> multi, final int limit,
      final BiFunction<ConsentPurposeFilter, ConsentPurposeCursor, Iterator<ConsentPurpose>> gateway,
      final ConsentPurposeFilter filter, final ConsentPurposeCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param consentPurposes
   * @param limit
   * @return
   */
  @Override
  public Iterator<ConsentPurpose> next(List<ConsentPurpose> consentPurposes, int limit) {
    ConsentPurpose last = consentPurposes.get(consentPurposes.size() - 1);
    ConsentPurposeCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
